begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)
select ('a1100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','integrated-'||n||'@example.test',now(),now(),now() from generate_series(1,3)n;
insert into public.organizations(id,name,slug,status) values('b1100000-0000-4000-8000-000000000001','Células integradas fictícias','cells-integrated-test','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('c1100000-0000-4000-8000-000000000001','b1100000-0000-4000-8000-000000000001','Sede fictícia','sede','headquarters');
insert into public.organization_memberships(id,organization_id,user_id,role,status,default_unit_id)
select ('e1100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b1100000-0000-4000-8000-000000000001',('a1100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n=1 then 'owner'::public.membership_role else 'viewer'::public.membership_role end,'active','c1100000-0000-4000-8000-000000000001' from generate_series(1,3)n;
insert into public.membership_unit_access(membership_id,unit_id,access_level) select id,'c1100000-0000-4000-8000-000000000001','read' from public.organization_memberships where organization_id='b1100000-0000-4000-8000-000000000001' and role='viewer';
insert into public.people(id,organization_id,unit_id,full_name,status,auth_user_id)
select ('d1100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001','Pessoa integrada '||n,'active',case when n<3 then ('a1100000-0000-4000-8000-'||lpad((n+1)::text,12,'0'))::uuid else null end from generate_series(1,3)n;
insert into public.church_cells(id,organization_id,unit_id,name,meeting_day,meeting_time,meeting_format,created_by)
select ('f1100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001','Grupo integrado '||n,1,'19:30','online','a1100000-0000-4000-8000-000000000001' from generate_series(1,2)n;
insert into public.church_cell_networks(id,organization_id,unit_id,name,status,created_by)
select ('fa110000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001','Rede integrada '||n,'active','a1100000-0000-4000-8000-000000000001' from generate_series(1,3)n;
insert into public.church_cell_network_parents(network_id,organization_id,unit_id,parent_id,updated_by) values('fa110000-0000-4000-8000-000000000002','b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001','fa110000-0000-4000-8000-000000000001','a1100000-0000-4000-8000-000000000001');
insert into public.church_cell_network_links(cell_id,organization_id,unit_id,network_id,updated_by)
select ('f1100000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001',('fa110000-0000-4000-8000-'||lpad((n+1)::text,12,'0'))::uuid,'a1100000-0000-4000-8000-000000000001' from generate_series(1,2)n;
create function pg_temp.plus(k text,id uuid,v integer,d jsonb default '{}') returns jsonb language sql as $$select public.cell_plus_save('b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001',k,id,v,d)$$;
create function pg_temp.readplus(k text,n uuid default null,c uuid default null,a uuid default null) returns jsonb language sql as $$select public.cell_plus_read('b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001',k,n,a,current_date-30,current_date,c)$$;
select ok(not has_function_privilege('anon','public.cell_plus_read(uuid,uuid,text,uuid,uuid,date,date,uuid)','EXECUTE'),'sem leitura anônima');
select ok(not has_function_privilege('authenticated','public.cell_report_reminder_batch(uuid)','EXECUTE'),'clientes não executam varredura global');
select ok(has_function_privilege('service_role','public.cell_report_reminder_batch(uuid)','EXECUTE'),'rotina apenas serviço');
select ok(not has_table_privilege('authenticated','private.cell_supervisor_grants','SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'concessões internas sem acesso direto');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(pg_temp.plus('referral','fb110000-0000-4000-8000-000000000001',0,'{"cell_id":"f1100000-0000-4000-8000-000000000001","person_id":null,"person_name":"Pessoa manual fictícia"}')->>'version','1','indicação manual não cria pessoa');
select throws_ok($$select pg_temp.plus('accept_referral','fb110000-0000-4000-8000-000000000001',1)$$,'22023','link_member_before_accept','não aceita sem vínculo de membro');
select is(pg_temp.plus('referral','fb110000-0000-4000-8000-000000000001',1,'{"cell_id":"f1100000-0000-4000-8000-000000000001","person_id":"d1100000-0000-4000-8000-000000000003","person_name":"Nome não confiável"}')->>'version','2','vincula cadastro existente');
select is(pg_temp.readplus('referrals')->'items'->0->>'person_name','Pessoa integrada 3','nome canônico do membro');
select is(pg_temp.plus('accept_referral','fb110000-0000-4000-8000-000000000001',2)->>'version','3','aceite cria participação');
select throws_ok($$select pg_temp.plus('accept_referral','fb110000-0000-4000-8000-000000000001',2)$$,'40001','cell_version_conflict','repetição não duplica participação');
select is((select count(*)::integer from public.church_cell_participants where cell_id='f1100000-0000-4000-8000-000000000001'),1,'um participante');
select lives_ok($$select public.cell_operations_save('b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001','meeting','f1100000-0000-4000-8000-000000000001','fc110000-0000-4000-8000-000000000001',0,jsonb_build_object('topic','Relatório pendente fictício','meeting_date',(now() at time zone 'America/Sao_Paulo')::date-1,'meeting_time','19:30','status','scheduled','present','[]'::jsonb))$$,'agendamento com chamada congelada');
select is(pg_temp.plus('material','fd110000-0000-4000-8000-000000000001',0,'{"network_id":null,"title":"Estudo fictício","body":"Conteúdo em texto seguro","url":"https://example.test/estudo.pdf","status":"draft"}')->>'version','1','material rascunho');
select throws_ok($$select pg_temp.plus('supervisor','fe110000-0000-4000-8000-000000000001',0,'{"network_id":"fa110000-0000-4000-8000-000000000001","person_id":"d1100000-0000-4000-8000-000000000003","capability":"report","status":"active"}')$$,'22023','supervisor_account_unavailable','não cria conta ou acesso implícito');
select is(pg_temp.plus('supervisor','fe110000-0000-4000-8000-000000000001',0,'{"network_id":"fa110000-0000-4000-8000-000000000001","person_id":"d1100000-0000-4000-8000-000000000001","capability":"read","status":"active"}')->>'version','1','concessão explícita de consulta');
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(jsonb_array_length(pg_temp.readplus('reports')->'cells'),1,'somente grupo da rede descendente');
select is(pg_temp.readplus('reports')->'summary'->>'groups','1','total completo autorizado');
select is(pg_temp.readplus('reports')->'summary'->>'participants','1','pessoa distinta');
select is(jsonb_array_length(pg_temp.readplus('materials')->'items'),0,'rascunho não visível ao supervisor');
select throws_ok($$select public.cell_directory_list_v2('b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001')$$,'42501','cell_access_denied','concessão não abre diretório geral antigo');
select throws_ok($$select pg_temp.readplus('reports','fa110000-0000-4000-8000-000000000003')$$,'42501','cell_access_denied','rede não concedida recusada');
select throws_ok($$select pg_temp.plus('notify','fc110000-0000-4000-8000-000000000001',1)$$,'42501','cell_access_denied','consulta não notifica');
select throws_ok($$select pg_temp.plus('report','fc110000-0000-4000-8000-000000000001',1,'{"present":[]}')$$,'42501','cell_access_denied','consulta não registra chamada');
select throws_ok($$select pg_temp.plus('material','fd110000-0000-4000-8000-000000000002',0,'{"network_id":null,"title":"Indevido","body":"","url":"","status":"published"}')$$,'42501','cell_access_denied','supervisor não publica materiais');
select throws_ok($$select pg_temp.readplus('supervisors')$$,'42501','cell_access_denied','supervisor não lista acessos de terceiros');
select is(pg_temp.readplus('roster',null,'f1100000-0000-4000-8000-000000000001')->>'canReport','false','interface conhece consulta sem escrita');
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(pg_temp.plus('material','fd110000-0000-4000-8000-000000000001',1,'{"network_id":null,"title":"Estudo fictício","body":"Conteúdo publicado","url":"https://example.test/estudo.pdf","status":"published"}')->>'version','2','publica estudo');
select is(pg_temp.plus('supervisor','fe110000-0000-4000-8000-000000000001',1,'{"network_id":"fa110000-0000-4000-8000-000000000001","person_id":"d1100000-0000-4000-8000-000000000001","capability":"report","status":"active"}')->>'version','2','ampliação explícita para relatório');
select is(pg_temp.plus('notify','fc110000-0000-4000-8000-000000000001',1)->>'notificationsCreated','1','aviso interno ao supervisor');
select is(pg_temp.plus('notify','fc110000-0000-4000-8000-000000000001',1)->>'notificationsCreated','0','não duplica aviso');
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(jsonb_array_length(pg_temp.readplus('materials')->'items'),1,'material publicado visível');
select is(pg_temp.readplus('pending')->'summary'->>'unread','1','aviso não lido');
select is(pg_temp.plus('read','fc110000-0000-4000-8000-000000000001',1)->>'version','1','marca somente o próprio aviso');
select is(pg_temp.readplus('pending')->'summary'->>'unread','0','contador atualizado');
select is(pg_temp.readplus('roster',null,'f1100000-0000-4000-8000-000000000001')->>'canReport','true','pode preencher chamada concedida');
select is(jsonb_array_length(pg_temp.readplus('roster',null,'f1100000-0000-4000-8000-000000000001')->'roster'),1,'chamada do encontro, não cadastro geral');
select throws_ok($$select pg_temp.plus('report','fc110000-0000-4000-8000-000000000001',1,'{"present":["d1100000-0000-4000-8000-000000000002"]}')$$,'22023','invalid_cell_plus','não inclui pessoa fora da fotografia');
select throws_ok($$select pg_temp.plus('report','fc110000-0000-4000-8000-000000000001',1,jsonb_build_object('present',jsonb_build_array((select id from public.church_cell_participants where cell_id='f1100000-0000-4000-8000-000000000001'))))$$,'22023','invalid_cell_plus','consulta geral continua sem acesso, usar chamada autorizada');
reset role;
-- The preceding authenticated SELECT is intentionally hidden by old RLS; use the scoped roster ID instead.
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select lives_ok($$select pg_temp.plus('report','fc110000-0000-4000-8000-000000000001',1,jsonb_build_object('present',jsonb_build_array(pg_temp.readplus('roster',null,'f1100000-0000-4000-8000-000000000001')->'roster'->0->>'participant_id')))$$,'registra usando apenas a chamada autorizada');
select is(pg_temp.readplus('reports')->'summary'->>'meetings','1','relatório consolidado realizado');
select is(pg_temp.readplus('reports')->'summary'->>'present','1','presença consolidada');
select is(pg_temp.readplus('pending')->'summary'->>'pending','0','pendência resolvida automaticamente');
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(pg_temp.plus('supervisor','fe110000-0000-4000-8000-000000000001',2,'{"network_id":"fa110000-0000-4000-8000-000000000001","person_id":"d1100000-0000-4000-8000-000000000001","capability":"report","status":"revoked"}')->>'version','3','revoga concessão');
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select pg_temp.readplus('reports')$$,'42501','cell_access_denied','revogação imediata na leitura');
select throws_ok($$select pg_temp.plus('report','fc110000-0000-4000-8000-000000000001',2,'{"present":[]}')$$,'42501','cell_access_denied','revogação imediata na escrita');
reset role;
select is((select count(*)::integer from public.people where organization_id='b1100000-0000-4000-8000-000000000001'),3,'nenhum membro criado implicitamente');
select is((select count(*)::integer from private.cell_report_notifications where organization_id='b1100000-0000-4000-8000-000000000001'),1,'uma notificação com histórico');
select ok(not exists(select 1 from private.cell_report_notifications where source='scheduled' and created_by is not null),'rotina não finge autoria humana');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(pg_temp.plus('supervisor','fe110000-0000-4000-8000-000000000001',3,'{"network_id":"fa110000-0000-4000-8000-000000000001","person_id":"d1100000-0000-4000-8000-000000000001","capability":"report","status":"active"}')->>'version','4','reativa concessão explícita');
select lives_ok($$select public.cell_operations_save('b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001','meeting','f1100000-0000-4000-8000-000000000001','fc110000-0000-4000-8000-000000000002',0,jsonb_build_object('topic','Rotina pendente fictícia','meeting_date',(now() at time zone 'America/Sao_Paulo')::date-2,'meeting_time','19:30','status','scheduled','present','[]'::jsonb))$$,'agendamento para rotina automática');
set local role service_role;
select lives_ok($$select public.cell_report_reminder_batch()$$,'serviço executa lote sem autenticação de cliente');
reset role;
select is((select count(*)::integer from private.cell_report_notifications where meeting_id='fc110000-0000-4000-8000-000000000002' and recipient_id='a1100000-0000-4000-8000-000000000002' and source='scheduled' and created_by is null),1,'notificação automática interna com autoria de sistema');
set local role service_role;
select lives_ok($$select public.cell_report_reminder_batch()$$,'repetir rotina é seguro');
reset role;
select is((select count(*)::integer from private.cell_report_notifications where meeting_id='fc110000-0000-4000-8000-000000000002'),1,'repetição da rotina não duplica');
update public.church_cell_network_parents set parent_id='fa110000-0000-4000-8000-000000000003',version=version+1 where network_id='fa110000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is(pg_temp.readplus('reports')->'summary'->>'groups','0','ramo movido deixa escopo anterior');
select throws_ok($$select pg_temp.plus('report','fc110000-0000-4000-8000-000000000002',1,'{"present":[]}')$$,'42501','cell_access_denied','reparentear remove escrita anterior');
reset role;
update public.church_cell_network_parents set parent_id='fa110000-0000-4000-8000-000000000001',version=version+1 where network_id='fa110000-0000-4000-8000-000000000002';
update public.church_cell_networks set status='archived' where id='fa110000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.readplus('reports')$$,'42501','cell_access_denied','rede concedida arquivada recusa escopo');
reset role;
update public.church_cell_networks set status='active' where id='fa110000-0000-4000-8000-000000000001';
update public.organization_memberships set status='suspended' where id='e1100000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select pg_temp.readplus('materials')$$,'42501','cell_access_denied','conta suspensa não lê materiais');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a1100000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.cell_plus_read('b1100000-0000-4000-8000-000000000099','c1100000-0000-4000-8000-000000000001','reports')$$,'42501','cell_access_denied','outro ministério recusado');
select throws_ok($$select pg_temp.readplus('roster','fa110000-0000-4000-8000-000000000001','f1100000-0000-4000-8000-000000000002')$$,'42501','cell_access_denied','chamada fora do filtro de ramo recusada');
reset role;
insert into public.saas_unit_contracts(organization_id,unit_id,payer_unit_id,plan_id,status,module_decisions) select 'b1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001','c1100000-0000-4000-8000-000000000001',id,'active','{"cells":true,"people":false}' from public.saas_plans where billing_cycle='monthly' limit 1;
set local role authenticated;
select throws_ok($$select pg_temp.readplus('reports')$$,'42501','cell_access_denied','módulo de Pessoas bloqueado impede consulta integrada');
select throws_ok($$select pg_temp.plus('notify','fc110000-0000-4000-8000-000000000002',1)$$,'42501','cell_access_denied','bloqueio contratual impede notificar');
reset role;
select * from finish();
rollback;
